const slots = $slots;
const attempts = slots.applicant.tickets.map((ticket) => ({ day: ticket.day, slotFrom: ticket.slotFrom, slotTo: ticket.slotTo }));
const open = (day) => day === slots.from || day === slots.to || day > slots.weekendFrom || day < slots.weekendTo;
const succeeds = (ticket) => open(ticket.day) && ticket.slotTo <= slots.lastTicketMinutes;
const matching = attempts.filter(succeeds);
if (matching.length !== 1) {
  throw new Error(matching.length + " attempts succeed instead of one");
}
return "Success: " + matching[0].day + " " + matching[0].slotFrom + "–" + matching[0].slotTo + ".";

