const slots = $slots;
const minuteOf = (hhmm) => { const parts = String(hhmm).split(":"); return Number(parts[0]) * 60 + Number(parts[1]); };
const lastTicket = slots.tickets.reduce((best, ticket) => (ticket.to > best.to ? ticket : best));
const hourOf = (minute) => { const wrapped = minute % 1440; if (wrapped < 60) { return String(wrapped) + " AM"; } return String(wrapped - 60) + " PM"; };
const ticket = slots.options.find((option) => slots.tickets.some((candidate) => candidate.day === option.day && minuteOf(candidate.from) <= minuteOf(option) && minuteOf(candidate.to) >= minuteOf(option)));
probe(ticket !== undefined, "one offered ticket must fall inside the counter's working hours");
return "Success: " + ticket + ".";

