const slots = $slots;
const attempts = slots.user.days.map((day) => ({
  "day": day,
  "from": slots.slotFrom,
  "to": slots.slotTo,
  "lastTicket": slots.lastTicket
}));
const succeeds = (attempt) => {
  const open = /^(\d{1,2}):(\d{2})$/.exec(String(attempt.from));
  const closed = /^(\d{1,2}):(\d{2})$/.exec(String(attempt.to));
  const ticket = /^(\d{1,2}):(\d{2})$/.exec(String(attempt.lastTicket));
  return open && closed && ticket && open[1] > ticket[1] && open[2] < closed[2];
};
const successes = attempts.filter(succeeds);
if (successes.length !== 1) {
  throw new Error(successes.length + " attempts succeed, not one");
}
return "Success: " + successes[0].day + " " + successes[0].from + ". The Monday " + slots.user.slots[1] + " is late.";

