const order = ["A", "B", "C", "D", "E"];
const ordered = order.map((name) => ({ name, duration: slots.durations[name], prerequisite: slots.requires[name], follows: slots.follows[name] }));
let progressed = false;
while (ordered.length > 0 && !progressed) {
  progressed = true;
  for (const entry of ordered) {
    if (entry.prerequisite !== null && !entry.prerequisite.every((name) => ordered.indexOf(name) < entry.name)) {
      progressed = false;
    }
  }
}
probe(ordered.every((entry) => entry.prerequisite.every((name) => ordered.indexOf(name) < entry.name)), "every prerequisite must be completed before the package");
probe(ordered.every((entry, index) => index === 0 || ordered[index - 1].duration <= entry.duration), "no package may come before a shorter prerequisite");
const safe = ordered.reduce((total, entry) => total + entry.duration, 0);
return "Safe completion time: " + safe + " minutes, so the plan " + (safe <= slots.limit ? "meets" : "does not meet") + " the limit.";

