const slots = $slots;
const order = [...slots.workPackages].sort((left, right) => left.minutes - right.minutes);
let elapsed = 0;
let completed = 0;
while (completed < slots.workPackages.length) {
  const available = order.filter((work) => work.minutes <= elapsed);
  if (available.length === 0) {
    throw new Error("no work package is ready to start at " + elapsed + " minutes");
  }
  elapsed += available.reduce((total, work) => total + work.minutes, 0);
  completed += available.length;
}
const safe = elapsed <= slots.limitMinutes + slots.bufferMinutes;
return safe ? "The earliest safe completion time is " + elapsed + " " + slots.unit + ", so the plan meets the limit." : "The earliest safe completion time is " + elapsed + " " + slots.unit + ", so the plan exceeds the limit.";

